<?php declare(strict_types=1); ?><!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>کاردان چوب | مدیریت سفارش‌ها</title><style>body{margin:0;background:#f5f1ec;color:#2b2119;font-family:Tahoma,Arial,sans-serif}.top{background:#241b15;color:#fff;padding:18px 5%;display:flex;justify-content:space-between;align-items:center}.top strong{font-size:20px}.wrap{max-width:1400px;margin:35px auto;padding:0 20px}.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:15px}.card{background:#fff;padding:20px;border:1px solid #e6ddd4;border-radius:10px}.card small{color:#8c7d70}.card b{display:block;font-size:25px;margin-top:8px}.toolbar{display:flex;gap:8px;flex-wrap:wrap;margin:25px 0}.toolbar button{border:1px solid #d8cbbd;background:#fff;padding:9px 14px;border-radius:5px;cursor:pointer}.toolbar button.active{background:#2b2119;color:#fff}.table{background:#fff;border-radius:10px;overflow:auto;border:1px solid #e6ddd4}table{width:100%;border-collapse:collapse;min-width:850px}th,td{text-align:right;padding:14px;border-bottom:1px solid #eee5dc;font-size:12px}th{background:#f8f4ef;color:#796b5e}.status{border-radius:15px;padding:5px 9px;font-size:10px}.pending{background:#fff0d7}.confirmed{background:#e2f0ff}.production{background:#e8e0ff}.ready{background:#e0f4e5}.shipped{background:#dff1f1}.completed{background:#dcefdc}.cancelled{background:#f8dddd}.change{padding:7px;border:1px solid #ddd0c3;border-radius:4px;background:#fff}.empty{text-align:center;padding:50px;color:#8c7d70}@media(max-width:800px){.cards{grid-template-columns:1fr 1fr}}</style></head><body><header class="top"><strong>کاردان چوب</strong><span>مدیریت سفارش‌های فروشگاه 3D</span></header><main class="wrap"><h1>داشبورد سفارش‌ها</h1><div class="cards"><div class="card"><small>کل سفارش‌ها</small><b id="total">۰</b></div><div class="card"><small>در انتظار بررسی</small><b id="pending">۰</b></div><div class="card"><small>در حال تولید</small><b id="production">۰</b></div><div class="card"><small>تکمیل‌شده</small><b id="completed">۰</b></div></div><div class="toolbar" id="filters"><button class="active" data-status="">همه</button><button data-status="pending">جدید</button><button data-status="confirmed">تأییدشده</button><button data-status="production">تولید</button><button data-status="ready">آماده</button><button data-status="shipped">ارسال</button><button data-status="completed">تکمیل</button><button data-status="cancelled">لغوشده</button></div><div class="table"><table><thead><tr><th>کد سفارش</th><th>مشتری</th><th>تماس</th><th>مبلغ</th><th>پرداخت</th><th>وضعیت</th><th>تاریخ</th></tr></thead><tbody id="rows"></tbody></table><div id="empty" class="empty" hidden>سفارشی پیدا نشد.</div></div></main><script>const labels={pending:'جدید',confirmed:'تأییدشده',production:'در تولید',ready:'آماده',shipped:'ارسال شده',completed:'تکمیل شده',cancelled:'لغو شده'};let orders=[];const fa=n=>Number(n||0).toLocaleString('fa-IR');async function load(status=''){const r=await fetch('../api/admin/orders.php'+(status?'?status='+encodeURIComponent(status):''));const j=await r.json();orders=j.orders||[];render(orders)}function render(list){document.querySelector('#total').textContent=fa(orders.length);document.querySelector('#pending').textContent=fa(orders.filter(x=>x.status==='pending').length);document.querySelector('#production').textContent=fa(orders.filter(x=>x.status==='production').length);document.querySelector('#completed').textContent=fa(orders.filter(x=>x.status==='completed').length);document.querySelector('#rows').innerHTML=list.map(o=>`<tr><td><b>${o.order_number}</b></td><td>${o.full_name}<br><small>${o.city||''}</small></td><td>${o.phone}</td><td>${fa(o.total_amount)} تومان</td><td>${o.payment_method}</td><td><select class="change" data-id="${o.id}" data-old="${o.status}"><option value="${o.status}">${labels[o.status]}</option>${Object.entries(labels).filter(([k])=>k!==o.status).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select></td><td>${new Date(o.created_at).toLocaleString('fa-IR')}</td></tr>`).join('');document.querySelector('#empty').hidden=list.length>0;document.querySelectorAll('.change').forEach(s=>s.onchange=async()=>{const r=await fetch('../api/admin/update-order-status.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({order_id:s.dataset.id,status:s.value})});const j=await r.json();if(!j.success){alert(j.message||'خطا');s.value=s.dataset.old}else{load(document.querySelector('.toolbar .active').dataset.status)}})}document.querySelectorAll('#filters button').forEach(b=>b.onclick=()=>{document.querySelectorAll('#filters button').forEach(x=>x.classList.remove('active'));b.classList.add('active');load(b.dataset.status)});load();</script></body></html>